#define USE_SHADOWS

#define DIST_MAX 1000.0


#define pi 3.1415926
#define tau (pi+pi)

mat3 yaw_pitch_roll(float yaw, float pitch, float roll)
{
    mat3 R = mat3(vec3(cos(yaw), sin(yaw), 0.0), vec3(-sin(yaw), cos(yaw), 0.0), vec3(0.0, 0.0, 1.0));
    mat3 S = mat3(vec3(1.0, 0.0, 0.0), vec3(0.0, cos(pitch), sin(pitch)), vec3(0.0, -sin(pitch), cos(pitch)));
    mat3 T = mat3(vec3(cos(roll), 0.0, sin(roll)), vec3(0.0, 1.0, 0.0), vec3(-sin(roll), 0.0, cos(roll)));

    return R * S * T;
}

vec4 combine(vec4 a, vec4 b)
{
    if(a.w < b.w) return a;
    return b;
}

vec4 rounded_cone_intersection(vec3 ro, vec3 rd, vec3 pa, vec3 pb, float ra, float rb) // modified https://iquilezles.org/articles/intersectors/
{
    vec3  ba = pb - pa;
    vec3  oa = ro - pa;
    vec3  ob = ro - pb;
    float rr = ra - rb;
    float m0 = dot(ba,ba);
    float m1 = dot(ba,oa);
    float m2 = dot(ba,rd);
    float m3 = dot(rd,oa);
    float m5 = dot(oa,oa);
    float m6 = dot(ob,rd);
    float m7 = dot(ob,ob);

    // body
    float d2 = m0-rr*rr;
    float k2 = d2    - m2*m2;
    float k1 = d2*m3 - m1*m2 + m2*rr*ra;
    float k0 = d2*m5 - m1*m1 + m1*rr*ra*2.0 - m0*ra*ra;
    float h = k1*k1 - k0*k2;
    if( h<0.0) return vec4(-rd, DIST_MAX);
    float t = (-sqrt(h)-k1)/k2;
  //if( t<0.0 ) return vec4(-rd, DIST_MAX);
    float y = m1 - ra*rr + t*m2;
    if( y>0.0 && y<d2 ) return vec4(normalize(d2*(oa+t*rd)-ba*y), t);

    // caps
    float h1 = m3*m3 - m5 + ra*ra;
    float h2 = m6*m6 - m7 + rb*rb;
    if( max(h1,h2)<0.0 ) return vec4(-rd, DIST_MAX);
    vec4 r = vec4(-rd, DIST_MAX);
    if( h1>0.0 )
    {
        t = -m3 - sqrt( h1 );
        r = vec4((oa+t*rd)/ra, t);
    }
    if( h2>0.0 )
    {
        t = -m6 - sqrt( h2 );
        if( t<r.w )
        r = vec4((ob+t*rd)/rb, t );
    }

    return r;
}

vec4 branch0(vec3 ro, vec3 rd, float scale, float thickness)
{
    // pa implied to be vec3(0,0,0)
    vec3 pb = vec3(0,0,1);

    return rounded_cone_intersection(ro, rd, vec3(0), pb, thickness, thickness * scale);
}

vec4 finalize(vec4 norm_dist, mat3 R, float scale)
{
    norm_dist.xyz = R * norm_dist.xyz;
    if(norm_dist.w < DIST_MAX) norm_dist.w *= scale;
    return norm_dist;
}

#define DEFINE_BRANCH(current, next) \
vec4 current(vec3 ro, vec3 rd, float scale, float thickness) \
{ \
    /* pa implied to be vec3(0,0,0) */ \
    vec3 pb = vec3(0,0,1); \
    /* NOTE: require 0 < scale < 1 */ \
    float limit = 1.0/(1.0-scale); \
    vec4 bound = rounded_cone_intersection(ro, rd, vec3(0), pb, thickness, limit * scale); \
    /* return bound; */ \
    if(bound.w < DIST_MAX) \
    { \
        float pitch = radians(45.0); \
        mat3 X = mat3(1,0,0,0,cos(pitch),sin(pitch),0,-sin(pitch),cos(pitch)); \
        /*mat3 Y = mat3(sin(pitch),0,cos(pitch),0,1,0,cos(pitch),0,-sin(pitch));*/ \
        float yaw = radians(120.0); \
        mat3 Z = mat3(cos(yaw),sin(yaw),0,-sin(yaw),cos(yaw),0,0,0,1); \
        vec4 tree = rounded_cone_intersection(ro, rd, vec3(0), pb, thickness, thickness * scale); \
        { \
            mat3 R = X; \
            vec4 q = finalize(next((ro-pb)*R/scale, rd*R, scale, thickness), R, scale); \
            tree = combine(tree, q); \
        } \
        { \
            mat3 R = Z*X; \
            vec4 q = finalize(next((ro-pb)*R/scale, rd*R, scale, thickness), R, scale); \
            tree = combine(tree, q); \
        } \
        { \
            mat3 R = Z*Z*X; \
            vec4 q = finalize(next((ro-pb)*R/scale, rd*R, scale, thickness), R, scale); \
            tree = combine(tree, q); \
        } \
        return tree; \
    } \
    return vec4(-rd, DIST_MAX); \
} \
// END

DEFINE_BRANCH(branch1, branch0)
DEFINE_BRANCH(branch2, branch1)
DEFINE_BRANCH(branch3, branch2)

struct result
{
    vec3 normal;
    float dist;
    vec3 color;
};

result combine(result a, result b)
{
    //return a.dist < b.dist ? a : b; // ??? why doesn't this compile ???
    if(a.dist < b.dist)
        return a;
    return b;
}

result trace(vec3 ro, vec3 rd)
{
    result current = result(-rd, DIST_MAX, vec3(0)); // sky sphere

    {
        float scale = 0.5;
        float thickness = 0.05;

        {
            vec4 res = branch3(ro, rd, scale, thickness);
            if(res.w > 0.0)
            {
                //vec3 color = mix(vec3(0.01),vec3(1.0),vec3(max(0.0, res.z))); // snow on branch (also verifies normal correctness)
                vec3 color = mix(vec3(0.01),vec3(1.0),vec3(1.0-pow(1.0-max(0.0, res.z),2.0))); // snow on branch (more contrast) (also verifies normal correctness)

                current = combine(current, result(res.xyz, res.w, color));
            }
        }

        {
            float t = (0.0-ro.z)/rd.z;
            if(t > 0.0)
            {
                vec3 n = vec3(0,0,1);
                vec3 color = vec3(1);
                current = combine(current, result(n, t, color));
            }
        }
    }

    return current;
}

void mainImage(out vec4 fragColor, in vec2 I)
{
    bool demo = all(lessThan(iMouse.xy, vec2(10.0)));
    vec2 R = iResolution.xy;
    I = (I + I - R) / R.y; // concise pixel-position mapping thanks to Fabrice
    float yaw = 2.0 * pi * float(iMouse.x) / float(R.x);
    float pitch = pi - pi / 2.0 * float(iMouse.y) / float(R.y);
    //float pitch = pi - pi * float(iMouse.y) / float(R.y);
    yaw = !demo ? yaw : 2.0 * pi * fract(iTime * 0.01);
    pitch = !demo ? pitch : 1.3 * pi/2.0; // circle flight demo

    vec3 ray_pos = vec3(0.0, 0.0, -3.0);
    vec3 ray_dir = vec3(I.x, I.y, 2.0);
    //ray_dir = normalize(ray_dir); // early normalize not enough on some systems (rotation introduces errors?)

    mat3 M = yaw_pitch_roll(yaw, pitch, 0.0);
    ray_pos = M * ray_pos;
    ray_dir = M * ray_dir;
    ray_dir = normalize(ray_dir); // late normalization more robust on systems with less accuracy
ray_pos.z += 0.5;
    result res = trace(ray_pos, ray_dir);
    vec3 color = res.color;

    vec3 skycolor = mix(vec3(0.2,0.4,0.8),vec3(0,0,1),abs(ray_dir.z));

    bool lighttype = true;
    //vec3 sun_dir = lighttype ? normalize(vec3(3,2,1)) : vec3(0);
    vec3 sun_dir = lighttype ? normalize(vec3(vec2(cos(iTime/10.0),sin(iTime/10.0)),2)) : vec3(0);
    float dim = lighttype ? 1.0-pow(max(0.0, dot(M * vec3(0,0,1), sun_dir)), 4.0) : 1.0; // reduce brightness when looking towards sun to make sunlight seem brighter
    if(res.dist < DIST_MAX)
    {
        res.normal *= dot(res.normal, ray_dir) < 0.0 ? +1.0 : -1.0; // repair front-back for thin surfaces

        vec3 dst = ray_pos + ray_dir * res.dist;
        float light = 0.0;
        vec3 light_dir = vec3(0);
        if(lighttype) // directional light
        {
            light_dir = sun_dir;
            light = 1.5;
#ifdef USE_SHADOWS
            light *= trace(dst+res.normal*0.001, light_dir).dist < DIST_MAX ? 0.0 : 1.0;
#endif
        }
        else // point light
        {
            light = 50.0;
            //vec3 light_pos = vec3(0,0,5);
            vec3 light_pos = vec3(5.0*vec2(cos(-iTime/5.0),sin(-iTime/5.0)),5);
            vec3 light_diff = light_pos - dst;
            float light_dist = length(light_diff);
            light_dir = light_diff / light_dist;
#ifdef USE_SHADOWS
            light *= trace(dst+res.normal*0.001, light_dir).dist < light_dist ? 0.0 : 1.0 / (light_dist * light_dist);
#endif
        }

        float brightness = light * max(0.0, dot(res.normal, light_dir));
        vec3 diffuse = vec3(brightness);
        float ambient = 0.1;

        //color *= (0.5 + 0.5 * res.normal); // visualize normals
        color *= (diffuse + ambient); // apply light
        //color = vec3(fract(result.w));

        if(brightness > 0.0)
        {
            float specular = pow(max(0.0, dot(res.normal, normalize(-ray_dir + light_dir))), 250.0);
            color += specular;
        }

        color = mix(skycolor, color, exp(-pow(distance(ray_pos.xy,dst.xy)/25.0, 2.0))); // distance fog (but not vertically)
    }
    else // sky
    {
        color = skycolor;
        if(true)
        {
            float d = max(0.0, dot(ray_dir, sun_dir));
            float sun = 50.0*smoothstep(0.999, 1.000, d) + exp(-pow((1.0-d)*1000.0, 2.0)); // sun with halo
            color += sun;
        }
    }
    //color *= dim;
    color = tanh(color); // roll-off / soft-clamp overly bright colors
    color = sqrt(color); // approximate gamma
    fragColor = vec4(color, 1.0);
}
